/* =============================================================================
 *  OWNED BY:  Vance — MusterChat call screen. Fully driven by callManager: it
 *  shows the incoming-call ring, the outgoing "calling…" state, and the live
 *  connected call (real remote + local video via WebRTC) with mute / camera /
 *  flip / hang-up. Rendered globally (by ChatBubble) so a call rings and runs
 *  on any page. Returns null when there's no call.
 * ============================================================================= */
import { useEffect, useRef, useState } from "react";
import { Mic, MicOff, Video, VideoOff, PhoneOff, Phone, SwitchCamera } from "lucide-react";
import callManager, { fmtCallDuration } from "../../lib/callManager.js";

const initialsOf = (n) => (n || "?").trim().split(/\s+/).map((w) => w[0]).slice(0, 2).join("").toUpperCase();

export default function VideoCallOverlay() {
  const [s, setS] = useState(callManager.snapshot());
  const [seconds, setSeconds] = useState(0);
  const localRef = useRef(null);
  const remoteRef = useRef(null);

  useEffect(() => callManager.subscribe(setS), []);
  useEffect(() => { if (localRef.current) localRef.current.srcObject = s.localStream || null; }, [s.localStream, s.status]);
  useEffect(() => { if (remoteRef.current) remoteRef.current.srcObject = s.remoteStream || null; }, [s.remoteStream, s.status]);

  useEffect(() => {
    if (s.status !== "connected") { setSeconds(0); return; }
    const id = setInterval(() => setSeconds(Math.floor((Date.now() - s.startedAt) / 1000)), 1000);
    return () => clearInterval(id);
  }, [s.status, s.startedAt]);

  // Brief error toast (declined / blocked) after a call ends.
  if (s.status === "idle") {
    if (!s.error) return null;
    return (
      <div style={{ position: "fixed", bottom: 24, left: "50%", transform: "translateX(-50%)", zIndex: 95, background: "#111", color: "#fff", padding: "10px 16px", borderRadius: 999, fontSize: 13, boxShadow: "0 10px 30px rgba(0,0,0,0.35)" }}>
        {s.error}
      </div>
    );
  }

  const { peer, mode, status } = s;
  const isIncoming = status === "incoming";
  const isVideo = mode === "video";
  const statusText = isIncoming ? `Incoming ${isVideo ? "video" : "voice"} call…`
    : status === "outgoing" ? `Calling…`
    : status === "connecting" ? "Connecting…"
    : fmtCallDuration(seconds);

  const ctrl = (active) => ({
    width: 52, height: 52, borderRadius: "50%", border: "none", cursor: "pointer",
    display: "inline-flex", alignItems: "center", justifyContent: "center",
    background: active ? "rgba(255,255,255,0.18)" : "rgba(255,255,255,0.92)", color: active ? "#fff" : "#111",
  });
  const roundBtn = (bg) => ({ width: 62, height: 62, borderRadius: "50%", border: "none", cursor: "pointer", background: bg, color: "#fff", display: "inline-flex", alignItems: "center", justifyContent: "center" });

  const showRemote = status === "connected" && s.remoteStream;

  return (
    <div style={{ position: "fixed", inset: 0, zIndex: 95, background: "#0b0b0f", color: "#fff", display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "space-between", padding: "28px 20px 34px" }}>
      {/* Remote / peer */}
      <div style={{ flex: 1, width: "100%", display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", gap: 16, position: "relative" }}>
        {showRemote ? (
          <video ref={remoteRef} autoPlay playsInline style={{ position: "absolute", inset: 0, width: "100%", height: "100%", objectFit: "cover" }} />
        ) : (
          <>
            <div style={{ width: 120, height: 120, borderRadius: "50%", background: "var(--scc-red, #E1232A)", display: "flex", alignItems: "center", justifyContent: "center", fontSize: 40, fontWeight: 700, boxShadow: status === "connected" ? "0 0 0 8px rgba(225,35,42,0.15)" : "none" }}>
              {initialsOf(peer?.name)}
            </div>
          </>
        )}
        <div style={{ textAlign: "center", zIndex: 1, position: showRemote ? "absolute" : "static", top: 24 }}>
          <div style={{ fontSize: 20, fontWeight: 600, textShadow: showRemote ? "0 1px 6px rgba(0,0,0,0.6)" : "none" }}>{peer?.name || "Contact"}</div>
          <div style={{ opacity: 0.85, fontSize: 14, marginTop: 4, textShadow: showRemote ? "0 1px 6px rgba(0,0,0,0.6)" : "none" }}>{statusText}</div>
        </div>
      </div>

      {/* Local camera PIP (once we have our own stream and it's a video call) */}
      {isVideo && s.localStream && !isIncoming && (
        <div style={{ position: "absolute", top: 24, right: 20, width: 120, height: 168, borderRadius: 14, overflow: "hidden", background: "#000", border: "1px solid rgba(255,255,255,0.2)" }}>
          <video ref={localRef} autoPlay muted playsInline style={{ width: "100%", height: "100%", objectFit: "cover", transform: "scaleX(-1)", display: s.camOn ? "block" : "none" }} />
          {!s.camOn && <div style={{ width: "100%", height: "100%", display: "flex", alignItems: "center", justifyContent: "center", color: "rgba(255,255,255,0.5)" }}><VideoOff size={22} /></div>}
        </div>
      )}

      {/* Controls */}
      {isIncoming ? (
        <div style={{ display: "flex", gap: 48, alignItems: "center" }}>
          <div style={{ textAlign: "center" }}>
            <button title="Decline" style={roundBtn("#ef4444")} onClick={() => callManager.reject()}><PhoneOff size={24} /></button>
            <div style={{ fontSize: 12, marginTop: 8, opacity: 0.8 }}>Decline</div>
          </div>
          <div style={{ textAlign: "center" }}>
            <button title="Accept" style={roundBtn("#22c55e")} onClick={() => callManager.accept()}><Phone size={24} /></button>
            <div style={{ fontSize: 12, marginTop: 8, opacity: 0.8 }}>Accept</div>
          </div>
        </div>
      ) : (
        <div style={{ display: "flex", gap: 18, alignItems: "center" }}>
          <button title={s.micOn ? "Mute" : "Unmute"} style={ctrl(s.micOn)} onClick={() => callManager.toggleMic()}>{s.micOn ? <Mic size={22} /> : <MicOff size={22} />}</button>
          {isVideo && (
            <>
              <button title={s.camOn ? "Camera off" : "Camera on"} style={ctrl(s.camOn)} onClick={() => callManager.toggleCam()}>{s.camOn ? <Video size={22} /> : <VideoOff size={22} />}</button>
              <button title="Flip camera" style={ctrl(true)} onClick={() => callManager.flipCam()}><SwitchCamera size={22} /></button>
            </>
          )}
          <button title="Hang up" style={roundBtn("#ef4444")} onClick={() => callManager.hangup()}><PhoneOff size={24} /></button>
        </div>
      )}
    </div>
  );
}

